examples:
// Common mistake: using = instead of ==
int x = 5;
// if (x = 10) { }  // Error: assignment, not comparison
if (x == 10) { }    // Correct: comparison

// Dangling else: else matches nearest if
if (x > 0)
    if (x > 5)
        System.out.println("x > 5");
    else  // This else belongs to the inner if
        System.out.println("0 < x <= 5");
